create_order_preview.code:
final response = await client.orderPreviews.createOrderPreview({
  'customer_id': 512,
  'delivery_type': 'shipping',
  'products': [
    {'product_id': 101, 'quantity': 2},
  ],
});
final order = (response.map as Map)['order'] as Map;
final session = order['session'] as Map;
print('${session['session_id']} ${session['expires_at']}');
print((order['totals'] as Map)['grand_total']);

get_order_preview.code:
final response =
    await client.orderPreviews.getOrderPreview('PRV-3f2a9c41b7d80e65');
final order = (response.map as Map)['order'] as Map;
final totals = order['totals'] as Map;
print('${totals['sub_total']} ${totals['shipping_cost']} ${totals['grand_total']}');

confirm_order_preview.code:
final response = await client.orderPreviews.confirmOrderPreview(
  'PRV-3f2a9c41b7d80e65',
  payload: {
    'send_email': false,
    'transaction_no': 'TXN-ORDER-0001',
    'payment': {
      'amount': 10.0,
      'payment_status': 'success',
      'payment_method': 'manual',
      'transaction_reference': 'REF-0001',
      'transaction_date': '2026-11-05T06:12:00Z',
    },
  },
);
final order = (response.map as Map)['order'] as Map;
print('${order['order_id']} ${order['order_status']} ${order['grand_total']}');

apply_order_preview_coupon.code:
final response = await client.orderPreviews
    .applyOrderPreviewCoupon('PRV-3f2a9c41b7d80e65', {'code': 'SAVE10'});
final order = (response.map as Map)['order'] as Map;
final coupon = (order['discounts'] as Map)['coupon'] as Map;
print('${coupon['code']} ${coupon['amount']}');
print((order['totals'] as Map)['grand_total']);

apply_order_preview_gift_card.code:
final response = await client.orderPreviews
